import java.util.Scanner;

public class Main {
    static final int MOD_BASE = 1000000007;
    static int mod = MOD_BASE;
    static int[] P = new int[1000001];

    static int add_mod(int a, int b) {
        int res = a + b;
        return res < mod ? res : res - mod;
    }

    static int multiply(int a, int b) {
        long res = (long) a * b;
        return (int) (res % mod);
    }

    static int power(int base, int exp) {
        int result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = multiply(result, base);
            }
            base = multiply(base, base);
            exp >>= 1;
        }
        return result;
    }

    static int baby_step_giant(int a, int m) {
        for (int i = 0; i < P.length; i++) {
            P[i] = -1;
        }
        int s = (int) Math.sqrt(m);
        mod = m;
        int r = a % m;
        int d = power(a, m - 2);
        for (int i = 0; i <= s; ++i) {
            if (P[r] == -1) P[r] = i;
            r = multiply(r, d);
            if (r == 1) {
                mod = MOD_BASE;
                return i + 1;
            }
        }
        d = power(a, s);
        r = d;
        for (int i = 1; i <= s; ++i) {
            if (P[r] > -1) {
                mod = MOD_BASE;
                return s * i + P[r];
            }
            r = multiply(r, d);
        }
        return -1;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int p = sc.nextInt();
        int k = sc.nextInt();

        if (k == 1) {
            System.out.println(power(p, p));
        } else if (k == 0) {
            System.out.println(power(p, p - 1));
        } else {
            int result = power(p, (p - 1) / baby_step_giant(k, p));
            System.out.println(result);
        }
        sc.close();
    }
}
